<script setup lang="ts">import{computed}from'vue';import{useAppStore}from'../stores/app';import{chapters}from'../data/chapters';import{BookmarkCheck,Volume2,Trash2}from'@lucide/vue';const store=useAppStore();const reviews=computed(()=>Object.values(store.progress.answers).filter(r=>store.progress.reviews.includes(r.choice.id)))</script>
<template><section class="page"><header class="page-head"><p class="eyebrow">REVIEW</p><h1>今日の復習</h1><p>{{store.activeCharacter.name}}との会話で出会った表現を、あなたのペースで。</p></header><div v-if="!reviews.length" class="empty"><BookmarkCheck/><h2>復習リストはまだ空です</h2><p>会話結果から、覚えたい英文を追加してみよう。</p><RouterLink class="primary" to="/story">ストーリーを選ぶ</RouterLink></div><div v-else class="review-list"><article v-for="r in reviews" class="card"><div><small>CHAPTER {{r.chapterId}}</small><button><Volume2/></button></div><h2>{{r.choice.naturalExpression}}</h2><p>{{r.choice.explanation}}</p><button class="remove" @click="store.toggleReview(r.choice.id)"><Trash2/> リストから外す</button></article></div><div class="expressions"><h3>学んだ表現</h3><p v-for="c in chapters.filter(c=>store.progress.completed.includes(c.id))" :key="c.id"><b>{{c.title}}</b><span>{{c.expressions.length}} expressions</span></p></div></section></template>
